    CONSTRAINT kept_node_kind_check CHECK ((kind = ANY (ARRAY['commit'::text, 'layer'::text, 'branch'::text, 'stack'::text]))),
    CONSTRAINT kept_node_layer_stack_id_check CHECK ((length(layer_stack_id) = 17)),
    CONSTRAINT kept_node_serial_check CHECK ((serial >= 0))
);


