    CONSTRAINT layer_logical_check CHECK ((logical >= 0)),
    CONSTRAINT layer_parent_layer_id_check CHECK (((parent_layer_id IS NULL) OR ((octet_length(parent_layer_id) = 33) AND (get_byte(parent_layer_id, 0) = 50)))),
    CONSTRAINT layer_root_id_check CHECK ((octet_length(root_id) = 32)),
    CONSTRAINT layer_source_branch_id_check CHECK (((source_branch_id IS NULL) OR ((octet_length(source_branch_id) = 17) AND (get_byte(source_branch_id, 0) = 17)))),
    CONSTRAINT layer_source_commit_id_check CHECK (((source_commit_id IS NULL) OR ((octet_length(source_commit_id) = 33) AND (get_byte(source_commit_id, 0) = 18))))
);


